#!/usr/bin/env node
// Generates the design-token CSS and the two Tailwind bridges from tokens.json (the one source of
// every value). Rule: .claude/rules/design-system.md.
//
//   node shared/design-tokens/build.mjs           # write the generated files
//   node shared/design-tokens/build.mjs --check   # CI: fail when a generated file is stale or a
//                                                 # text / UI colour pair falls below WCAG AA
//
// Generated (never edit by hand):
//   primitives.css               layer 1: raw values (--zinc-50, --blue-600, --dim-8, --type-13)
//   theme.css                    layer 2: semantic tokens (--color-surface, --radius-control, …);
//                                light on :root, dark on .dark, admin density on
//                                [data-density="comfortable"], user-chosen colours as --data-*
//   tailwind-bridge.app.cjs      Tailwind 3 preset for client/ (adds semantic class names only)
//   tailwind-bridge.admin.css    Tailwind 4 for admin/: shadcn variables + @theme registration
//
// The bridges are add-only: an existing class name in either app keeps exactly the value it had
// before the tokens arrived. Where an existing name will later point at a token, the bridge says
// so (APP_TAKEN, ADMIN_SHADCN below) and the switch happens in a later, visible PR.
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const DIR = path.dirname(fileURLToPath(import.meta.url))
const T = JSON.parse(fs.readFileSync(path.join(DIR, 'tokens.json'), 'utf8'))
const GENERATED = 'Generated by shared/design-tokens/build.mjs from tokens.json. Do not edit.'

const entries = group => Object.fromEntries(Object.entries(group).filter(([k]) => !k.startsWith('$')).map(([k, v]) => [k, v.$value]))

const PRIM = Object.assign({}, ...Object.values(T.primitive).map(entries))
const S = T.semantic
const SCALE = entries(S.scale)
const LIGHT = entries(S.light)
const DARK = entries(S.dark)
const DENSITY = entries(S.density.comfortable)
const DATA = {
  'data-department-default': T.data['department-default'].$value,
  ...Object.fromEntries(Object.entries(entries(T.data['department-palette'])).map(([k, v]) => [`data-department-${k.slice(1)}`, v])),
}

const fail = msg => { throw new Error(`tokens.json: ${msg}`) }
const sameKeys = (a, b) => Object.keys(a).sort().join() === Object.keys(b).sort().join()
if (!sameKeys(LIGHT, DARK)) fail('semantic.light and semantic.dark must define the same names')
for (const k of Object.keys(DENSITY)) if (!(k in SCALE)) fail(`density.comfortable.${k} overrides nothing in semantic.scale`)

const REF = /^\{primitive\.[a-z-]+\.([a-z0-9-]+)\}$/
const refName = v => (typeof v === 'string' ? REF.exec(v)?.[1] : undefined)
function cssValue(v) {
  const r = refName(v)
  if (r) { if (!(r in PRIM)) fail(`unknown reference ${v}`); return `var(--${r})` }
  if (Array.isArray(v)) {
    return v.every(x => typeof x === 'number')
      ? `cubic-bezier(${v.join(', ')})`
      : v.map(x => (/\s/.test(x) ? `'${x}'` : x)).join(', ')
  }
  return String(v)
}
const resolved = v => (refName(v) ? PRIM[refName(v)] : v)
const rgbChannels = hex => [1, 3, 5].map(i => parseInt(hex.slice(i, i + 2), 16)).join(' ')
/** `--color-x-rgb: r g b` for every hex colour: Tailwind 3's opacity modifier (bg-x/50) needs channels. */
const channels = d => Object.fromEntries(Object.entries(d)
  .filter(([k, v]) => k.startsWith('color-') && /^#[0-9a-f]{6}$/i.test(resolved(v)))
  .map(([k, v]) => [`${k}-rgb`, rgbChannels(resolved(v))]))
const block = (sel, d) => `${sel} {\n${Object.entries(d).map(([k, v]) => `  --${k}: ${cssValue(v)};\n`).join('')}}\n`

// ---------------------------------------------------------------- layer 1 and 2 (CSS)

const primitivesCss = `/* Layer 1: raw values. ${GENERATED}\n   Components never use these directly; use the semantic names in theme.css. */\n${block(':root', PRIM)}`

const themeCss = `/* Layer 2: semantic tokens. ${GENERATED}
   Light on :root; dark under .dark (both apps put the class on <html>). The admin console sets
   <html data-density="comfortable"> (14px body, 36px controls); the app uses the default.
   --color-*-rgb are channels for Tailwind 3's opacity modifier. --data-* are user-chosen colours
   (data, not meaning). No color-scheme here: each app sets its own today. */
${block(':root', { ...SCALE, ...DATA })}
${block('[data-density="comfortable"]', DENSITY)}
${block(':root', { ...LIGHT, ...channels(LIGHT) })}
${block('.dark', { ...DARK, ...channels(DARK) })}`

// ---------------------------------------------------------------- bridges

const COLORS = Object.keys(LIGHT).filter(k => k.startsWith('color-')).map(k => k.slice('color-'.length))
const STEPS = ['caption', 'small', 'body', 'title', 'heading', 'page']
const RADII = ['small', 'control', 'card']
const SHADOWS = ['card', 'pop', 'dialog']
const LAYERS = ['overlay', 'dialog', 'menu', 'toast']
const HEIGHTS = { control: 'size-control', 'control-sm': 'size-control-sm', 'control-lg': 'size-control-lg' }
const SIZES = { 'icon-sm': 'size-icon-sm', icon: 'size-icon', 'icon-lg': 'size-icon-lg', 'icon-state': 'size-icon-state', tap: 'size-tap' }
const PADDINGS = Object.fromEntries(Object.keys(SCALE).filter(k => k.startsWith('padding-')).map(k => [k.slice('padding-'.length), k]))

// Colour names the desktop app's tailwind.config.js already defines with a fixed value
// (`bg-surface` is #ffffff in both themes, `border-border` #e0e0e0). The bridge leaves them alone:
// they switch to the tokens when the screens using them move to the semantic names (P1 dark mode).
const APP_TAKEN = ['surface', 'border']

const appPreset = {
  theme: {
    extend: {
      colors: Object.fromEntries(COLORS.filter(c => !APP_TAKEN.includes(c)).map(c => [c,
        c === 'scrim' ? 'var(--color-scrim)' : `rgb(var(--color-${c}-rgb) / <alpha-value>)`])),
      fontSize: Object.fromEntries(STEPS.map(n => [n, [`var(--font-size-${n})`,
        { lineHeight: `var(--line-height-${n})`, fontWeight: `var(--weight-${n})` }]])),
      fontWeight: { strong: 'var(--weight-strong)' },
      fontFamily: { body: 'var(--font-family-body)' },
      borderRadius: Object.fromEntries(RADII.map(r => [r, `var(--radius-${r})`])),
      boxShadow: Object.fromEntries(SHADOWS.map(s => [s, `var(--shadow-${s})`])),
      zIndex: Object.fromEntries(LAYERS.map(z => [z, `var(--z-${z})`])),
      opacity: { disabled: 'var(--opacity-disabled)' },
      height: Object.fromEntries(Object.entries(HEIGHTS).map(([k, v]) => [k, `var(--${v})`])),
      minHeight: Object.fromEntries(Object.entries(HEIGHTS).map(([k, v]) => [k, `var(--${v})`])),
      size: Object.fromEntries(Object.entries(SIZES).map(([k, v]) => [k, `var(--${v})`])),
      padding: Object.fromEntries(Object.entries(PADDINGS).map(([k, v]) => [k, `var(--${v})`])),
      borderWidth: { strong: 'var(--border-width-strong)' },
      ringWidth: { focus: 'var(--focus-ring-width)' },
      ringOffsetWidth: { focus: 'var(--focus-ring-offset)' },
      outlineWidth: { focus: 'var(--focus-ring-width)' },
      outlineOffset: { focus: 'var(--focus-ring-offset)' },
      transitionDuration: { fast: 'var(--duration-fast)' },
      transitionTimingFunction: { standard: 'var(--ease)' },
    },
  },
}
const appBridge = `// Tailwind 3 preset for the desktop app (client/tailwind.config.js \`presets\`). ${GENERATED}
// Adds the semantic class names (bg-surface-raised, text-text-muted, bg-danger-bg, text-body,
// rounded-control, z-dialog, …); colours go through rgb(var(--color-…-rgb) / <alpha-value>), so an
// opacity modifier works. Existing names (accent, surface, border, text-sm, rounded-lg, …) are not
// touched. The CSS variables come from primitives.css + theme.css (imported by src/index.css).
module.exports = ${JSON.stringify(appPreset, null, 2)}
`

// shadcn/ui's variables in the admin console → the semantic token each one stands for. The admin's
// own colours stay until the per-component PRs switch them (owner decision 6: Geist → system font):
// a row with `keep` emits today's value for that theme, and the comment names the token it moves
// to. Remove a `keep` = a visible change: do it in the component's PR. Dropped so far: light
// card / popover (exact matches), primary / primary-foreground (P2a, owner decision 2: the black
// primary buttons became the primary blue).
const ADMIN_SHADCN = [
  ['background', 'color-bg', 'oklch(0.99 0 0)', 'oklch(0.16 0.004 286)'],
  ['foreground', 'color-text', 'oklch(0.21 0.006 285.9)', 'oklch(0.96 0 0)'],
  ['card', 'color-surface', null, 'oklch(0.19 0.005 286)'],
  ['card-foreground', 'color-text', 'oklch(0.21 0.006 285.9)', 'oklch(0.96 0 0)'],
  ['popover', 'color-surface-raised', null, 'oklch(0.21 0.006 286)'],
  ['popover-foreground', 'color-text', 'oklch(0.21 0.006 285.9)', 'oklch(0.96 0 0)'],
  ['primary', 'color-primary', null, null],
  ['primary-foreground', 'color-on-primary', null, null],
  ['secondary', 'color-surface-sunken', 'oklch(0.967 0.001 286.4)', 'oklch(0.26 0.006 286)'],
  ['secondary-foreground', 'color-text', 'oklch(0.21 0.006 285.9)', 'oklch(0.96 0 0)'],
  ['muted', 'color-surface-sunken', 'oklch(0.967 0.001 286.4)', 'oklch(0.24 0.006 286)'],
  ['muted-foreground', 'color-text-muted', 'oklch(0.5 0.014 285.9)', 'oklch(0.72 0.012 286)'],
  // shadcn's `accent` is "pale hover background", not the app's blue accent: it maps to sunken.
  ['accent', 'color-surface-sunken', 'oklch(0.955 0.003 286.3)', 'oklch(0.26 0.006 286)'],
  ['accent-foreground', 'color-text', 'oklch(0.21 0.006 285.9)', 'oklch(0.96 0 0)'],
  ['destructive', 'color-danger', 'oklch(0.577 0.245 27.3)', 'oklch(0.66 0.2 22)'],
  ['destructive-foreground', 'color-on-danger', 'oklch(0.985 0 0)', 'oklch(0.985 0 0)'],
  ['warning', 'color-warning-text', 'oklch(0.6 0.13 70)', 'oklch(0.8 0.14 80)'],
  ['success', 'color-success-text', 'oklch(0.55 0.13 155)', 'oklch(0.75 0.15 155)'],
  ['brand', 'color-link', 'oklch(0.51 0.2 277)', 'oklch(0.7 0.15 277)'],
  ['border', 'color-border', 'oklch(0.92 0.004 286.3)', 'oklch(1 0 0 / 10%)'],
  ['input', 'color-border-control', 'oklch(0.89 0.004 286.3)', 'oklch(1 0 0 / 15%)'],
  ['ring', 'color-focus-ring', 'oklch(0.51 0.2 277)', 'oklch(0.7 0.15 277)'],
  ['sidebar', 'color-bg', 'oklch(0.975 0.001 286.4)', 'oklch(0.14 0.004 286)'],
  ['sidebar-foreground', 'color-text', 'oklch(0.21 0.006 285.9)', 'oklch(0.96 0 0)'],
  ['sidebar-accent', 'color-surface-sunken', 'oklch(0.93 0.003 286.3)', 'oklch(0.23 0.006 286)'],
  ['sidebar-border', 'color-border', 'oklch(0.92 0.004 286.3)', 'oklch(1 0 0 / 8%)'],
]
for (const [, target] of ADMIN_SHADCN) if (!(target in LIGHT)) fail(`ADMIN_SHADCN target ${target} is not a semantic token`)
// Semantic colour names the admin's shadcn registration already uses for its own variable.
const ADMIN_TAKEN = new Set(ADMIN_SHADCN.map(([name]) => name))
const shadcnVar = (name, target, keep) => (keep
  ? `  --${name}: ${keep}; /* later: var(--${target}) */\n`
  : `  --${name}: var(--${target});\n`)

const adminBridge = `/* Tailwind 4 bridge for the admin console (admin/src/app/globals.css imports it after
   primitives.css and theme.css). ${GENERATED}
   1. shadcn/ui's variables, as aliases of the semantic tokens. Where the alias would change what
      the admin shows today, today's value is kept and the comment names the token it moves to.
   2. Their @theme registration (bg-primary, text-muted-foreground, rounded-lg, …), unchanged in
      what the classes produce; \`reference\`, so no --color-primary of its own is emitted next to
      the token of that name.
   3. The semantic class names, added (bg-surface-raised, text-text-muted, bg-danger-bg, text-body,
      rounded-control, shadow-dialog, z-dialog, px-control-x, …); sizes and paddings are spacing
      names, so every axis works (h-control, size-icon, px-control-x, py-toast-y). \`inline reference\`: utilities read the token
      variable directly and no second variable of the same name is emitted. */
:root {
  --radius: var(--radius-control);
${ADMIN_SHADCN.map(([n, t, light]) => shadcnVar(n, t, light)).join('')}}

.dark {
${ADMIN_SHADCN.map(([n, t, , dark]) => shadcnVar(n, t, dark)).join('')}}

@theme inline reference {
${ADMIN_SHADCN.map(([n]) => `  --color-${n}: var(--${n});\n`).join('')}  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
}

@theme inline reference {
${COLORS.filter(c => !ADMIN_TAKEN.has(c)).map(c => `  --color-${c}: var(--color-${c});\n`).join('')}\
${RADII.map(r => `  --radius-${r}: var(--radius-${r});\n`).join('')}\
${STEPS.map(n => `  --text-${n}: var(--font-size-${n});\n  --text-${n}--line-height: var(--line-height-${n});\n  --text-${n}--font-weight: var(--weight-${n});\n`).join('')}\
  --font-weight-strong: var(--weight-strong);
  --font-body: var(--font-family-body);
${SHADOWS.map(s => `  --shadow-${s}: var(--shadow-${s});\n`).join('')}\
${Object.entries({ ...HEIGHTS, ...SIZES, ...PADDINGS }).map(([k, v]) => `  --spacing-${k}: var(--${v});\n`).join('')}\
  --ease-standard: var(--ease);
}

${LAYERS.map(z => `@utility z-${z} {\n  z-index: var(--z-${z});\n}\n`).join('')}\
@utility opacity-disabled {
  opacity: var(--opacity-disabled);
}
@utility duration-fast {
  --tw-duration: var(--duration-fast);
  transition-duration: var(--duration-fast);
}
@utility border-strong {
  border-width: var(--border-width-strong);
}
@utility ring-focus {
  --tw-ring-shadow: var(--tw-ring-inset,) 0 0 0 calc(var(--focus-ring-width) + var(--tw-ring-offset-width)) var(--tw-ring-color, currentcolor);
  box-shadow: var(--tw-inset-shadow), var(--tw-inset-ring-shadow), var(--tw-ring-offset-shadow), var(--tw-ring-shadow), var(--tw-shadow);
}
`

// ---------------------------------------------------------------- contrast (WCAG 2)

function luminance(hex) {
  const c = [1, 3, 5].map(i => parseInt(hex.slice(i, i + 2), 16) / 255)
    .map(x => (x <= 0.04045 ? x / 12.92 : ((x + 0.055) / 1.055) ** 2.4))
  return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2]
}
const ratio = (a, b) => { const [hi, lo] = [luminance(a), luminance(b)].sort((x, y) => y - x); return (hi + 0.05) / (lo + 0.05) }
const TEXT = 4.5, UI = 3
// [foreground, background, required]. Text needs 4.5:1; icons, borders, focus rings, button shapes 3:1.
const PAIRS = [
  ...['bg', 'surface', 'surface-raised', 'surface-sunken'].flatMap(bg => [['text', bg, TEXT], ['text-muted', bg, TEXT]]),
  ['text-subtle', 'surface', TEXT], ['text-subtle', 'bg', TEXT],
  ['on-primary', 'primary', TEXT], ['on-primary', 'primary-hover', TEXT],
  ['link', 'surface', TEXT], ['link', 'bg', TEXT],
  ['selected-text', 'selected-bg', TEXT], ['text', 'selected-bg', TEXT], ['text', 'selected-bg-hover', TEXT],
  ['on-danger', 'danger', TEXT], ['on-danger', 'danger-hover', TEXT],
  ['danger-text', 'surface', TEXT], ['danger-text', 'danger-bg', TEXT], ['danger-text', 'surface-raised', TEXT],
  ['danger-text', 'danger-bg-hover', TEXT],
  ...['warning', 'success', 'ai'].flatMap(s => [[`${s}-text`, `${s}-bg`, TEXT], [`${s}-text`, 'surface', TEXT]]),
  ['info-text', 'info-bg', TEXT],
  ...['paused', 'failed', 'awaiting', 'readonly'].map(s => [`${s}-text`, `${s}-bg`, TEXT]),
  ['private-text', 'surface', TEXT], ['on-toast', 'toast', TEXT],
  ['selected-icon', 'selected-bg', UI], ['danger-icon', 'danger-bg', UI], ['readonly-icon', 'readonly-bg', UI],
  ['warning-icon', 'warning-bg', UI], ['success-icon', 'surface', UI], ['ai-icon', 'surface', UI],
  ['focus-ring', 'surface', UI], ['focus-ring', 'bg', UI], ['focus-ring', 'surface-raised', UI],
  ['border-strong', 'surface', UI], ['primary', 'surface', UI], ['danger', 'surface', UI], ['unread', 'surface', UI],
  ...['task', 'decision', 'project', 'meeting'].map(t => [`thing-${t}`, 'surface', UI]),
]
function contrastFailures() {
  const out = []
  for (const [theme, d] of [['light', LIGHT], ['dark', DARK]]) {
    for (const [fg, bg, need] of PAIRS) {
      const r = ratio(resolved(d[`color-${fg}`]), resolved(d[`color-${bg}`]))
      if (r < need) out.push(`${theme}: color-${fg} on color-${bg} is ${r.toFixed(2)}:1, needs ${need}:1`)
    }
  }
  return out
}

// ---------------------------------------------------------------- write / check

const OUTPUTS = {
  'primitives.css': primitivesCss,
  'theme.css': themeCss,
  'tailwind-bridge.app.cjs': appBridge,
  'tailwind-bridge.admin.css': adminBridge,
}

if (process.argv.includes('--check')) {
  const problems = Object.entries(OUTPUTS)
    .filter(([f, text]) => !fs.existsSync(path.join(DIR, f)) || fs.readFileSync(path.join(DIR, f), 'utf8') !== text)
    .map(([f]) => `${f} is not what tokens.json generates: run node shared/design-tokens/build.mjs and commit the result`)
  problems.push(...contrastFailures())
  for (const p of problems) console.error(`::error::design tokens: ${p}`)
  if (problems.length === 0) console.log(`design tokens: ${Object.keys(OUTPUTS).length} generated files up to date; ${PAIRS.length * 2} colour pairs meet WCAG AA`)
  process.exit(problems.length ? 1 : 0)
} else {
  for (const [f, text] of Object.entries(OUTPUTS)) fs.writeFileSync(path.join(DIR, f), text)
  const failures = contrastFailures()
  for (const f of failures) console.warn(`contrast: ${f}`)
  console.log(`wrote ${Object.keys(OUTPUTS).join(', ')}${failures.length ? ` (${failures.length} contrast failures)` : ''}`)
}
